"use client";

import React, { useState, useEffect } from "react";
import { Clock } from "lucide-react";

interface OrderCountdownProps {
  expiresAt?: string | null;
  createdAt?: string | null;
  className?: string;
}

export const OrderCountdown = React.memo(function OrderCountdown({
  expiresAt,
  createdAt,
  className = "",
}: OrderCountdownProps) {
  const [countdown, setCountdown] = useState(() => calculateCountdown(expiresAt, createdAt));

  useEffect(() => {
    // Initial compute
    setCountdown(calculateCountdown(expiresAt, createdAt));

    const interval = setInterval(() => {
      const next = calculateCountdown(expiresAt, createdAt);
      setCountdown(next);
      if (next.isExpired) {
        clearInterval(interval);
      }
    }, 1000);

    return () => clearInterval(interval);
  }, [expiresAt, createdAt]);

  return (
    <div className={`inline-flex items-center gap-1 font-mono text-xs ${className}`}>
      <Clock className="w-3 h-3 text-amber-400 shrink-0" />
      <span
        className={
          countdown.isExpired
            ? "text-rose-400 font-medium"
            : "text-amber-400 font-medium tabular-nums"
        }
      >
        {countdown.text}
      </span>
    </div>
  );
});

function calculateCountdown(expiresAtStr?: string | null, createdAtStr?: string | null) {
  let targetTime: number;
  if (expiresAtStr) {
    targetTime = new Date(expiresAtStr).getTime();
  } else if (createdAtStr) {
    // 15-minute lease from creation time
    targetTime = new Date(createdAtStr).getTime() + 15 * 60 * 1000;
  } else {
    return { text: "—", isExpired: false };
  }

  const diffSec = Math.floor((targetTime - Date.now()) / 1000);
  if (diffSec <= 0) {
    return { text: "Expired", isExpired: true };
  }
  const mins = Math.floor(diffSec / 60);
  const secs = diffSec % 60;
  return {
    text: `${mins}:${secs < 10 ? "0" : ""}${secs}`,
    isExpired: false,
  };
}
